 const kpis=[['Trips completed',String(trips.length),'Operational'],['Revenue',money(revenue),'Income'],['Fuel expense',money(fuelExpense),'Expense'],['Driver / assistant expense',money(driverExpense+assistantExpense),'Expense'],['Maintenance',money(maintenanceExpense),'Expense'],['Other operating expenses',money(otherExpense),'Expense'],['Operating cash balance',money(received-expenses),'Cash'],['Receivable',money(revenue-received),'Outstanding'],['Estimated gross margin',`${margin.toFixed(1)}%`,'Margin'],['Truck utilization',`${utilization.toFixed(0)}%`,selectedId?'Selected vehicle':'Fleet']];
